const tabId = 480038377;
const startX = 524;
const startY = 510;
const endX = 755;
const endY = 510;

await tool.mouse({ action: "move", tabId, coordinate: [startX, startY] });
await tool.mouse({ action: "down", tabId, coordinate: [startX, startY] });

const steps = 15;
for (let i = 1; i <= steps; i++) {
  const x = Math.round(startX + (endX - startX) * (i / steps));
  const y = startY + Math.round((Math.random() - 0.5) * 2);
