const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const startX = 524;
const startY = 510;
const endX = 755;
const endY = 510;

// Move to start
await tool.cdp({
  tabId,
  method: "Input.dispatchMouseEvent",
  params: { type: "mouseMoved", x: startX, y: startY, buttons: 0 }
});
await sleep(100);

// Press down
await tool.cdp({
  tabId,
  method: "Input.dispatchMouseEvent",
  params: { type: "mousePressed", x: startX, y: startY, button: "left", buttons: 1, clickCount: 1 }
});
await sleep(150);

// Drag across
const steps = 25;
for (let i = 1; i <= steps; i++) {
  const t = i / steps;
  // slight easing
  const x = Math.round(startX + (endX - startX) * t);
  const y = startY + Math.round(Math.sin(t * Math.PI) * 3);
  await tool.cdp({
    tabId,
    method: "Input.dispatchMouseEvent",
    params: { type: "mouseMoved", x, y, buttons: 1 }
  });
  await sleep(30);
}

await sleep(150);

// Release up
await tool.cdp({
  tabId,
  method: "Input.dispatchMouseEvent",
  params: { type: "mouseReleased", x: endX, y: endY, button: "left", buttons: 0 }
});

console.log("Drag completed. Waiting for response...");
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

const pageInfo = await browserjs(tabId, () => ({
  title: document.title,
  url: window.location.href,
  bodyText: document.body?.innerText?.slice(0, 300)
}));
console.log("Page info after drag:", JSON.stringify(pageInfo, null, 2));

