// Let's inspect the wav file duration and properties
const tabId = 480038377;
const audioMeta = await browserjs(tabId, async (url) => {
  const resp = await fetch(url);
  const buf = await resp.arrayBuffer();
  const view = new DataView(buf);
  const channels = view.getUint16(22, true);
  const sampleRate = view.getUint32(24, true);
  const bitsPerSample = view.getUint16(34, true);
  const dataSize = view.getUint32(40, true);
  const durationSec = dataSize / (sampleRate * channels * (bitsPerSample / 8));
  return { channels, sampleRate, bitsPerSample, dataSize, durationSec };
}, wavUrl);

console.log("Audio metadata:", audioMeta);

